class TestSolverStrategyContract:
    """Verify the abstract base class enforces its contract."""

    def test_abstract_class_cannot_be_instantiated(self):
        """SolverStrategy should be abstract and non-instantiable."""
        with pytest.raises(TypeError):
            SolverStrategy()

    def test_abstract_methods_defined(self):
        """SolverStrategy must declare abstract methods."""
        abstract_methods = SolverStrategy.__abstractmethods__
        assert 'solve' in abstract_methods
        assert 'validate_expression' in abstract_methods

    def test_concrete_subclass_must_implement_abstract_methods(self):
        """A subclass missing abstract methods should not be instantiable."""
        class IncompleteStrategy(SolverStrategy):
            pass

        with pytest.raises(TypeError):
            IncompleteStrategy()

    def test_concrete_subclass_with_all_methods_instantiable(self):
        """A fully-implemented subclass should be instantiable."""
        class CompleteStrategy(SolverStrategy):
            def solve(self, expression: sympy.Expr, variable: sympy.Symbol) -> List[Any]:
                return []

            def validate_expression(self, expression: Any) -> bool:
                return isinstance(expression, sympy.Expr)

        strategy = CompleteStrategy()
        assert strategy is not None

    def test_validate_expression_rejects_non_sympy(self, symbolic_strategy):
        """validate_expression should reject non-sympy inputs."""
        assert not symbolic_strategy.validate_expression(42)
        assert not symbolic_strategy.validate_expression("x + 1")
        assert not symbolic_strategy.validate_expression(None)
        assert not symbolic_strategy.validate_expression([1, 2, 3])

    def test_validate_expression_accepts_sympy_expr(self, symbolic_strategy):
        """validate_expression should accept sympy expressions."""
        x = sympy.Symbol('x')
        assert symbolic_strategy.validate_expression(x + 1)
        assert symbolic_strategy.validate_expression(sympy.sin(x))
        assert symbolic_strategy.validate_expression(sympy.Integer(5))


