class TestSymbolicStrategy:
    """Test exact symbolic solution handling."""

    def test_linear_equation(self, symbolic_strategy, linear_expression):
        """Linear equation x - 3 = 0 should yield x = 3."""
        x = sympy.Symbol('x')
        solutions = symbolic_strategy.solve(linear_expression, x)
        assert len(solutions) == 1
        assert sympy.simplify(solutions[0] - 3) == 0

    def test_quadratic_equation(self, symbolic_strategy, quadratic_expression):
        """Quadratic x² - 4 = 0 should yield x = ±2."""
        x = sympy.Symbol('x')
        solutions = symbolic_strategy.solve(quadratic_expression, x)
        assert len(solutions) == 2
        solution_set = {sympy.simplify(sol) for sol in solutions}
        assert sympy.Integer(2) in solution_set
        assert sympy.Integer(-2) in solution_set

    def test_cubic_equation(self, symbolic_strategy, cubic_expression):
        """Cubic x³ - 6x² + 11x - 6 = 0 should yield x = 1, 2, 3."""
        x = sympy.Symbol('x')
        solutions = symbolic_strategy.solve(cubic_expression, x)
        assert len(solutions) == 3
        solution_set = {sympy.simplify(sol) for sol in solutions}
        assert sympy.Integer(1) in solution_set
        assert sympy.Integer(2) in solution_set
        assert sympy.Integer(3) in solution_set

    def test_no_real_solution(self, symbolic_strategy, no_solution_expression):
        """x² + 1 = 0 should yield complex roots, not real."""
        x = sympy.Symbol('x')
        solutions = symbolic_strategy.solve(no_solution_expression, x)
        assert len(solutions) == 2
        for sol in solutions:
            assert sympy.im(sol) != 0  # Complex roots

    def test_infinite_solutions(self, symbolic_strategy, infinite_solution_expression):
        """0 = 0 should indicate infinite solutions."""
        x = sympy.Symbol('x')
        solutions = symbolic_strategy.solve(infinite_solution_expression, x)
        # Should return a sentinel or empty list indicating infinite solutions
        assert solutions == [] or solutions == [sympy.Symbol('x')]

    def test_transcendental_equation(self, symbolic_strategy, transcendental_expression):
        """sin(x) - 0.5 = 0 should have symbolic solutions."""
        x = sympy.Symbol('x')
        solutions = symbolic_strategy.solve(transcendental_expression, x)
        assert len(solutions) >= 1
        # Verify at least one solution satisfies the equation
        for sol in solutions:
            residual = sympy.simplify(transcendental_expression.subs(x, sol))
            assert abs(float(residual.evalf())) < 1e-10

    def test_invalid_expression_type(self, symbolic_strategy):
        """Non-sympy input should raise appropriate exception."""
        with pytest.raises((TypeError, ValueError)):
            symbolic_strategy.solve("x + 1", sympy.Symbol('x'))

    def test_undefined_variable(self, symbolic_strategy, linear_expression):
        """Solving for a variable not in the expression should raise."""
        y = sympy.Symbol('y')
        with pytest.raises((ValueError, sympy.SympifyError)):
            symbolic_strategy.solve(linear_expression, y)


