    def test_quadratic_equation(self, numerical_strategy_default, quadratic_expression):
        """Quadratic should converge to x ≈ ±2."""
        x = sympy.Symbol('x')
        solutions = numerical_strategy_default.solve(quadratic_expression, x)
        assert len(solutions) == 2
