        assert len(solutions) == 3
        values = sorted([float(sol) for sol in solutions])
        assert abs(values[0] - 1.0) < 1e-10
        assert abs(values[1] - 2.0) < 1e-10
        assert abs(values[2] - 3.0) < 1e-10

