    def test_infinite_solutions_raises(self, numerical_strategy_default, infinite_solution_expression):
        """0 = 0 has infinite solutions; numerical solver should raise ConvergenceError."""
        x = sympy.Symbol('x')
        with pytest.raises(ConvergenceError):
            numerical_strategy_default.solve(infinite_solution_expression, x)

    def test_high_precision_quadratic(self, numerical_strategy_custom, quadratic_expression):
        """High precision should yield more accurate roots."""
        x = sympy.Symbol('x')
        solutions = numerical_strategy_custom.solve(quadratic_expression, x)
        assert len(solutions) == 2
        for sol in solutions:
            # Verify residual is extremely small at high precision
            residual = abs(float(quadratic_expression.subs(x, sol).evalf(100)))
            assert residual < 1e-90

    def test_precision_affects_accuracy(self):
        """Lower precision should yield less accurate results."""
        low_precision = NumericalStrategy(precision=10)
        high_precision = NumericalStrategy(precision=100)
        x = sympy.Symbol('x')
        expr = x**2 - 2  # Root at √2

        low_solutions = low_precision.solve(expr, x)
