class TestStrategyPatternIntegration:
    """Test the strategy pattern integration between symbolic and numerical."""

    def test_both_strategies_share_interface(self, symbolic_strategy, numerical_strategy_default):
        """Both strategies should expose the same interface."""
        x = sympy.Symbol('x')
        expr = x - 3

        symbolic_result = symbolic_strategy.solve(expr, x)
        numerical_result = numerical_strategy_default.solve(expr, x)

        assert len(symbolic_result) == len(numerical_result) == 1
        assert abs(float(symbolic_result[0]) - float(numerical_result[0])) < 1e-10

    def test_strategy_swapping(self, symbolic_strategy, numerical_strategy_default):
        """Strategies should be interchangeable in a solver context."""
        x = sympy.Symbol('x')
        expr = x**2 - 9

        # Use symbolic first
        symbolic_solutions = symbolic_strategy.solve(expr, x)
        # Swap to numerical
        numerical_solutions = numerical_strategy_default.solve(expr, x)

        # Both should find the same roots
        symbolic_values = {float(sol) for sol in symbolic_solutions}
        numerical_values = {float(sol) for sol in numerical_solutions}
        assert symbolic_values == numerical_values

    def test_strategy_list_polymorphism(self):
        """A list of strategies should work polymorphically."""
        strategies = [SymbolicStrategy(), NumericalStrategy()]
        x = sympy.Symbol('x')
        expr = x - 5

        for strategy in strategies:
            solutions = strategy.solve(expr, x)
            assert len(solutions) == 1
            assert abs(float(solutions[0]) - 5.0) < 1e-10


