class TestPropertyBasedValidation:
    """Property-based tests validating numerical against symbolic results."""

    @given(st.floats(min_value=-100, max_value=100, allow_nan=False, allow_infinity=False))
    @settings(max_examples=50, deadline=None)
    def test_linear_equation_property(self, a):
        """For any a, solving x - a = 0 should yield x = a."""
        x = sympy.Symbol('x')
        expr = x - a

        symbolic = SymbolicStrategy().solve(expr, x)
        numerical = NumericalStrategy().solve(expr, x)

        assert len(symbolic) == len(numerical) == 1
        assert abs(float(symbolic[0]) - a) < 1e-8
        assert abs(float(numerical[0]) - a) < 1e-8

    @given(st.floats(min_value=0.1, max_value=100, allow_nan=False, allow_infinity=False))
    @settings(max_examples=50, deadline=None)
    def test_quadratic_equation_property(self, a):
        """For any a > 0, solving x² - a² = 0 should yield x = ±a."""
        x = sympy.Symbol('x')
        expr = x**2 - a**2

        symbolic = SymbolicStrategy().solve(expr, x)
        numerical = NumericalStrategy().solve(expr, x)

        assert len(symbolic) == len(numerical) == 2
        symbolic_values = {abs(float(sol)) for sol in symbolic}
        numerical_values = {abs(float(sol)) for sol in numerical}
        assert symbolic_values == numerical_values
        assert abs(min(symbolic_values) - a) < 1e-8

    @given(st.integers(min_value=1, max_value=10))
    @settings(max_examples=20, deadline=None)
    def test_polynomial_roots_property(self, n):
        """For polynomial (x-1)(x-2)...(x-n), roots should be 1..n."""
        x = sympy.Symbol('x')
        expr = sympy.Integer(1)
        for i in range(1, n + 1):
            expr *= (x - i)

        symbolic = SymbolicStrategy().solve(expr, x)
        assert len(symbolic) == n

        symbolic_values = {float(sol) for sol in symbolic}
        expected_values = {float(i) for i in range(1, n + 1)}
        assert symbolic_values == expected_values

    @given(st.floats(min_value=-10, max_value=10, allow_nan=False, allow_infinity=False))
    @settings(max_examples=30, deadline=None)
    def test_numerical_residual_property(self, a):
        """Numerical solutions should have near-zero residual."""
        x = sympy.Symbol('x')
        expr = x**3 - a

        try:
            numerical = NumericalStrategy().solve(expr, x)
        except ConvergenceError:
            pytest.skip("Solver failed to converge for this input")

        for sol in numerical:
            residual = abs(float(expr.subs(x, sol).evalf()))
            assert residual < 1e-6


