class TestEdgeCases:
    """Test edge cases and error handling."""

    def test_empty_expression(self, symbolic_strategy, numerical_strategy_default):
        """Empty or None expression should raise."""
        x = sympy.Symbol('x')
        with pytest.raises((TypeError, ValueError)):
            symbolic_strategy.solve(None, x)
        with pytest.raises((TypeError, ValueError)):
            numerical_strategy_default.solve(None, x)

    def test_constant_expression(self, symbolic_strategy, numerical_strategy_default):
        """Constant expression (no variable) should raise."""
        x = sympy.Symbol('x')
        expr = sympy.Integer(5)
        with pytest.raises((ValueError, sympy.SympifyError)):
            symbolic_strategy.solve(expr, x)
        with pytest.raises((ValueError, sympy.SympifyError)):
            numerical_strategy_default.solve(expr, x)

    def test_expression_without_target_variable(self, symbolic_strategy, numerical_strategy_default):
        """Expression not containing the target variable should raise."""
        x = sympy.Symbol('x')
        y = sympy.Symbol('y')
        expr = y**2 - 4
        with pytest.raises((ValueError, sympy.SympifyError)):
            symbolic_strategy.solve(expr, x)
        with pytest.raises((ValueError, sympy.SympifyError)):
            numerical_strategy_default.solve(expr, x)

    def test_high_degree_polynomial(self, symbolic_strategy):
        """High-degree polynomial should still be solvable symbolically."""
        x = sympy.Symbol('x')
        expr = x**5 - x**4 - 5*x**3 + x**2 + 8*x + 4  # Roots at -1, -1, 1, 2, -2
        solutions = symbolic_strategy.solve(expr, x)
        assert len(solutions) == 5

    def test_numerical_initial_guess_sensitivity(self):
        """Numerical solver should handle multiple initial guesses."""
        x = sympy.Symbol('x')
        expr = x**2 - 4

        strategy = NumericalStrategy()
        solutions = strategy.solve(expr, x)
        assert len(solutions) == 2

    def test_mpmath_precision_consistency(self):
        """mpmath precision should match strategy precision."""
        strategy = NumericalStrategy(precision=80)
        assert mp.prec == 80 or mp.dps >= 24  # mpmath precision should be set

    def test_sympy_mpf_conversion(self, numerical_strategy_default):
        """Solutions should be convertible to mpf."""
        x = sympy.Symbol('x')
        expr = x - 3
        solutions = numerical_strategy_default.solve(expr, x)
        for sol in solutions:
            mpf_val = mpf(str(sol))
            assert abs(float(mpf_val) - 3.0) < 1e-10


